def get_trust_page_content(slug: str, brand_name: str = "Styleire", domain: str = "styleire.com") -> dict[str, Any]:
    """Retrieves formatted content for a given trust/legal slug, substituting brand name and domain."""
    data = TRUST_PAGES_METADATA.get(slug)
    if not data:
        return {
            "slug": slug,
            "title": slug.replace("-", " ").title(),
            "subtitle": "",
            "content_html": f"<p>Information regarding Copyright will be available shortly.</p>",
        }
    
    title = data["title"].replace("Styleire", brand_name)
    subtitle = data["subtitle"].replace("Styleire", brand_name)
    content = (
        data["content_html"]
        .replace("styleire.com", domain)
        .replace("Styleire", brand_name)
        .replace("../../", "/")
        .replace("../", "/")
    )
    return {
        "slug": slug,
        "title": title,
        "subtitle": subtitle,
        "content_html": content,
    }
